//! Milestone 2, acceptance criterion: an AI agent turns an image of an
//! alphabet into a complete font through MCP, with no GUI, in both protocol
//! eras. The image is our own specimen (`tests/fixtures/hito2/specimen.png`,
//! generated by code; no third-party material).
//!
//! When `FORMA_ACCEPTANCE_OUT` names a folder, the legacy-era run leaves
//! `hito2-specimen.ttf`, `hito2-specimen.woff2`, `hito2-specimen.forma` and
//! `hito2-expected.json` there for the external oracles. Format of
//! `hito2-expected.json`:
//! * `format`: a short description of the file;
//! * `family`, `upm`;
//! * `glyphs`: `{name: {"unicodes": ["U+0041", ...], "advance": int}}`
//!   (advance widths rounded, as compiled);
//! * `cmap`: `{"U+0041": "A", ...}`;
//! * `shaping`: `{"text", "glyphs"}`: the glyph names `text` shapes to;
//! * `kerning`: `[{"left", "right", "value"}]`, the effective glyph-to-glyph
//!   kerning (exceptions first, then glyph-group, group-glyph, group-group)
//!   for every pair of the traced letters whose value is not 0.

mod mcp_common;

use std::collections::BTreeMap;
use std::path::Path;
use std::time::{Duration, Instant};

use mcp_common::{
    ACTOR, Client, call, close, connect, copy_specimen, decode_png, is_legacy, legacy, modern,
    path_text, with_timeout_for,
};
use read_fonts::types::GlyphId;
use read_fonts::{FontRef, TableProvider};
use rmcp::ClientLifecycleMode;
use rstest::rstest;
use serde_json::{Value, json};

/// The letters of the specimen, in candidate order (reading order).
const LETTERS: [char; 8] = ['A', 'B', 'C', 'H', 'O', 'F', 'M', 'R'];

/// The text the external shaping check sets.
const SHAPING_TEXT: &str = "HOAMAR";

#[rstest]
#[case::legacy(legacy())]
#[case::modern(modern())]
#[tokio::test]
async fn image_to_font_scenario(#[case] mode: ClientLifecycleMode) {
    with_timeout_for(
        "image_to_font_scenario",
        Duration::from_secs(120),
        scenario(mode),
    )
    .await;
}

fn unicode_text(code: u32) -> String {
    format!("U+{code:04X}")
}

async fn scenario(mode: ClientLifecycleMode) {
    let started = Instant::now();
    let legacy = is_legacy(&mode);
    let (client, root) = connect(mode, &[]).await;
    let root = root.path();
    let image = copy_specimen(root, "specimen.png");
    let image_text = path_text(&image);

    // 1. document_create "Specimen Demo".
    let created = call(
        &client,
        "document_create",
        json!({ "family_name": "Specimen Demo", "units_per_em": 1000 }),
    )
    .await
    .ok();
    let doc = created["doc"].as_str().expect("doc").to_owned();
    let mut rev = created["rev"].as_u64().expect("rev");
    assert_eq!(rev, 0);
    let inspected = call(&client, "document_inspect", json!({ "doc": doc }))
        .await
        .ok();
    assert_eq!(
        inspected["masters"][0]["metrics"]["cap_height"].as_f64(),
        Some(700.0),
        "{inspected}"
    );

    // 2. image_inspect: the image and 8 candidates.
    let inspected = call(&client, "image_inspect", json!({ "path": image_text })).await;
    assert!(!inspected.is_error, "{:?}", inspected.json);
    assert!(
        !inspected.structured,
        "an image result has no structured content"
    );
    let png = inspected.image.as_deref().expect("an image block");
    let pixmap = decode_png(png);
    assert!(pixmap.width() > 0 && pixmap.height() > 0);
    let summary = inspected.json.expect("summary");
    assert_eq!(summary["candidates_total"], json!(8), "{summary}");
    assert_eq!(summary["candidates_truncated"], json!(false), "{summary}");
    assert_eq!(summary["candidates"].as_array().map(Vec::len), Some(8));

    // 3. image_trace: candidate i -> LETTERS[i], upper and lower case.
    let assignments: Vec<Value> = LETTERS
        .iter()
        .enumerate()
        .map(|(candidate, letter)| {
            let upper = u32::from(*letter);
            json!({ "candidate": candidate, "name": letter.to_string(),
                    "unicodes": [unicode_text(upper), unicode_text(upper + 32)] })
        })
        .collect();
    let traced = call(
        &client,
        "image_trace",
        json!({ "doc": doc, "base_rev": rev, "path": image_text, "assignments": assignments }),
    )
    .await
    .ok();
    rev = traced["rev"].as_u64().expect("rev");
    assert_eq!(rev, 1, "{traced}");
    let list = traced["traced"].as_array().expect("traced");
    assert_eq!(list.len(), 8, "{traced}");
    let mut ious = Vec::new();
    for (entry, letter) in list.iter().zip(LETTERS) {
        assert_eq!(entry["name"], json!(letter.to_string()), "{traced}");
        let iou = entry["iou"].as_f64().expect("iou");
        assert!(iou >= 0.97, "iou of {letter} is {iou}: {traced}");
        ious.push(iou);
    }
    eprintln!("[hito2] ious: {ious:?}");

    // Plain glyphs the font needs besides the letters.
    let ops = vec![
        json!({ "tool": "glyph_create", "args": { "name": ".notdef", "advance_width": 500,
            "svg_path": "M50 0 L450 0 L450 700 L50 700 Z M100 50 L100 650 L400 650 L400 50 Z" } }),
        json!({ "tool": "glyph_create", "args": { "name": "space", "advance_width": 250,
            "unicodes": ["U+0020"] } }),
        json!({ "tool": "glyph_create", "args": { "name": "acutecomb", "advance_width": 0,
            "unicodes": ["U+0301"] } }),
        json!({ "tool": "glyph_create", "args": { "name": "zero", "advance_width": 600,
            "unicodes": ["U+0030"] } }),
    ];
    let batch = call(
        &client,
        "edit_batch",
        json!({ "doc": doc, "base_rev": rev, "label": "Create the plain glyphs", "ops": ops }),
    )
    .await
    .ok();
    rev = batch["rev"].as_u64().expect("rev");

    // 4. geometry_check: nothing wrong with the traced outlines.
    let check = call(&client, "geometry_check", json!({ "doc": doc }))
        .await
        .ok();
    assert_eq!(check["issues"], json!([]), "{check}");

    // 5. glyph_measure on H.
    let measured = call(
        &client,
        "glyph_measure",
        json!({ "doc": doc, "glyph": "H" }),
    )
    .await
    .ok();
    let stroke = measured["stroke_median"].as_f64().expect("stroke_median");
    assert!(stroke > 0.0, "{measured}");
    eprintln!("[hito2] glyph_measure H: {measured}");

    // 6. glyph_stroke: acutecomb (diagonal, ball ends) and zero (closed oval).
    let stroked = call(
        &client,
        "glyph_stroke",
        json!({ "doc": doc, "base_rev": rev, "glyph": "acutecomb",
                "skeletons": [{ "closed": false, "nodes": [
                    { "x": 200, "y": 740, "kind": "line" },
                    { "x": 330, "y": 860, "kind": "line" } ] }],
                "width": stroke * 0.8,
                "cap": { "type": "bulb", "ratio": 1.4 }, "mode": "replace" }),
    )
    .await
    .ok();
    rev = stroked["rev"].as_u64().expect("rev");
    let oval: Vec<Value> = (0..16)
        .map(|step| {
            let angle = f64::from(step) * std::f64::consts::TAU / 16.0;
            json!({ "x": (300.0 + 200.0 * angle.cos()).round(),
                    "y": (350.0 + 310.0 * angle.sin()).round(), "kind": "line" })
        })
        .collect();
    let stroked = call(
        &client,
        "glyph_stroke",
        json!({ "doc": doc, "base_rev": rev, "glyph": "zero",
                "skeletons": [{ "closed": true, "nodes": oval }],
                "width": stroke, "cap": { "type": "round" }, "mode": "replace" }),
    )
    .await
    .ok();
    rev = stroked["rev"].as_u64().expect("rev");

    // 7. glyph_compose: Aacute and Oacute.
    for (name, base, upper) in [("Aacute", "A", 0xC1_u32), ("Oacute", "O", 0xD3)] {
        let composed = call(
            &client,
            "glyph_compose",
            json!({ "doc": doc, "base_rev": rev, "name": name,
                    "unicodes": [unicode_text(upper), unicode_text(upper + 32)],
                    "base": base,
                    "marks": [{ "glyph": "acutecomb", "position": "above" }] }),
        )
        .await
        .ok();
        rev = composed["rev"].as_u64().expect("rev");
    }

    // 8. spacing_auto: 14 glyphs is under the mass-edit threshold of 20, so
    //    it applies without approval.
    let spaced = call(
        &client,
        "spacing_auto",
        json!({ "doc": doc, "base_rev": rev }),
    )
    .await
    .ok();
    rev = spaced["rev"].as_u64().expect("rev");
    eprintln!("[hito2] spacing_auto: {spaced}");

    // 9. kerning_auto dry run, then plan_commit.
    let planned = call(
        &client,
        "kerning_auto",
        json!({ "doc": doc, "base_rev": rev, "dry_run": true }),
    )
    .await
    .ok();
    let token = planned["plan"]["plan_token"]
        .as_str()
        .unwrap_or_else(|| panic!("no plan token: {planned}"))
        .to_owned();
    let committed = call(&client, "plan_commit", json!({ "plan_token": token }))
        .await
        .ok();
    assert_eq!(committed["plan_committed"], json!(true), "{committed}");
    rev = committed["rev"].as_u64().expect("rev");
    assert!(rev > 0);

    // 10. kerning_check: no collisions, with kerning_auto's own minimum
    //     distance (2 % of the em) and with overlaps only.
    for min_distance in [20.0, 0.0] {
        let checked = call(
            &client,
            "kerning_check",
            json!({ "doc": doc, "min_distance": min_distance }),
        )
        .await
        .ok();
        assert_eq!(
            checked["collisions_total"],
            json!(0),
            "{min_distance}: {checked}"
        );
        assert!(
            checked["checked_pairs"].as_u64().unwrap_or(0) > 0,
            "{checked}"
        );
        eprintln!(
            "[hito2] kerning_check min_distance {min_distance}: {} pairs",
            checked["checked_pairs"]
        );
    }
    let kerning = call(&client, "kerning_get", json!({ "doc": doc }))
        .await
        .ok();
    eprintln!(
        "[hito2] kerning: {} pairs, {} groups",
        kerning["pairs_total"], kerning["groups_total"]
    );
    assert!(
        kerning["pairs_total"].as_u64().unwrap_or(0) > 0,
        "{kerning}"
    );

    // 11. charset_check: the letters, lower case, space, Á á Ó ó and 0.
    let mut codepoints: Vec<u32> = LETTERS
        .iter()
        .flat_map(|letter| [u32::from(*letter), u32::from(*letter) + 32])
        .collect();
    codepoints.extend([0x20, 0xC1, 0xE1, 0xD3, 0xF3, 0x30]);
    let charset = call(
        &client,
        "charset_check",
        json!({ "doc": doc, "codepoints": codepoints }),
    )
    .await
    .ok();
    assert_eq!(charset["coverage"].as_f64(), Some(1.0), "{charset}");
    assert_eq!(charset["missing"], json!([]), "{charset}");

    // 12. validate: no errors.
    let validated = call(&client, "validate", json!({ "doc": doc })).await.ok();
    assert_eq!(validated["report"]["errors"], json!(0), "{validated}");
    assert_eq!(validated["report"]["compiled"], json!(true), "{validated}");

    // 13. export_font TTF and WOFF2.
    let model = model_glyphs(&client, &doc).await;
    let ttf_path = root.join("hito2-specimen.ttf");
    let exported = call(
        &client,
        "export_font",
        json!({ "doc": doc, "base_rev": rev, "format": "ttf", "path": path_text(&ttf_path) }),
    )
    .await
    .ok();
    assert_eq!(exported["rev"], json!(rev), "{exported}");
    let ttf = std::fs::read(&ttf_path).expect("the TTF");
    check_ttf(&ttf, &model);
    let woff2_path = root.join("hito2-specimen.woff2");
    call(
        &client,
        "export_font",
        json!({ "doc": doc, "base_rev": rev, "format": "woff2", "path": path_text(&woff2_path) }),
    )
    .await
    .ok();
    let woff2 = std::fs::read(&woff2_path).expect("the WOFF2");
    assert!(woff2.starts_with(b"wOF2"), "not a WOFF2 file");

    // 15 (before saving). The history is attributed to the test agent.
    let history = call(&client, "history_list", json!({ "doc": doc }))
        .await
        .ok();
    let entries = history["entries"].as_array().expect("entries");
    assert!(entries.len() >= 8, "{history}");
    for entry in entries {
        assert_eq!(entry["actor"], json!(ACTOR), "{entry}");
    }

    // 14. document_save, close, open: kerning and components are identical.
    let kerning_before = call(&client, "kerning_get", json!({ "doc": doc }))
        .await
        .ok();
    let mut before = Vec::new();
    for name in ["Aacute", "Oacute", "acutecomb", "zero"] {
        before.push(
            call(&client, "glyph_get", json!({ "doc": doc, "glyph": name }))
                .await
                .ok()["glyph"]
                .clone(),
        );
    }
    let forma_path = root.join("hito2-specimen.forma");
    call(
        &client,
        "document_save",
        json!({ "doc": doc, "base_rev": rev, "path": path_text(&forma_path) }),
    )
    .await
    .ok();
    call(&client, "document_close", json!({ "doc": doc }))
        .await
        .ok();
    let opened = call(
        &client,
        "document_open",
        json!({ "path": path_text(&forma_path) }),
    )
    .await
    .ok();
    let reopened = opened["doc"].as_str().expect("doc").to_owned();
    let kerning_after = call(&client, "kerning_get", json!({ "doc": reopened }))
        .await
        .ok();
    assert_eq!(kerning_after["pairs"], kerning_before["pairs"]);
    assert_eq!(kerning_after["groups"], kerning_before["groups"]);
    for (name, expected) in ["Aacute", "Oacute", "acutecomb", "zero"]
        .iter()
        .zip(&before)
    {
        let got = call(
            &client,
            "glyph_get",
            json!({ "doc": reopened, "glyph": name }),
        )
        .await
        .ok();
        assert_eq!(&got["glyph"], expected, "{name}");
    }
    // Aacute = [A, acutecomb] and Oacute = [O, acutecomb], placed as before.
    for (index, (name, base)) in [("Aacute", "A"), ("Oacute", "O")].into_iter().enumerate() {
        let components = &before[index]["components"];
        let bases: Vec<&Value> = components
            .as_array()
            .expect("components")
            .iter()
            .map(|component| &component["base"])
            .collect();
        assert_eq!(
            bases,
            [&json!(base), &json!("acutecomb")],
            "{name}: {components}"
        );
        assert!(
            components[1]["transform"]["dy"].as_f64().is_some(),
            "{components}"
        );
        let got = call(
            &client,
            "glyph_get",
            json!({ "doc": reopened, "glyph": name }),
        )
        .await
        .ok();
        assert_eq!(&got["glyph"]["components"], components, "{name}");
    }
    let charset = call(
        &client,
        "charset_check",
        json!({ "doc": reopened, "codepoints": [0xC1, 0xD3] }),
    )
    .await
    .ok();
    assert_eq!(
        charset["composite"],
        json!(["Aacute", "Oacute"]),
        "{charset}"
    );
    assert_eq!(charset["outlined"], json!([]), "{charset}");

    if legacy && let Some(out) = std::env::var_os("FORMA_ACCEPTANCE_OUT") {
        write_acceptance(Path::new(&out), root, &model, &kerning_after);
    }
    eprintln!("[hito2] scenario took {:?}", started.elapsed());
    close(client).await;
}

/// One glyph of the model, as `glyph_list` reports it.
#[derive(Clone, Debug)]
struct ModelGlyph {
    name: String,
    unicodes: Vec<u32>,
    advance_width: f64,
}

async fn model_glyphs(client: &Client, doc: &str) -> Vec<ModelGlyph> {
    let listed = call(client, "glyph_list", json!({ "doc": doc, "limit": 500 }))
        .await
        .ok();
    listed["glyphs"]
        .as_array()
        .expect("glyphs")
        .iter()
        .map(|glyph| ModelGlyph {
            name: glyph["name"].as_str().expect("name").to_owned(),
            unicodes: glyph["unicodes"]
                .as_array()
                .expect("unicodes")
                .iter()
                .map(|code| u32::try_from(code.as_u64().expect("code point")).expect("u32"))
                .collect(),
            advance_width: glyph["advance_width"].as_f64().expect("advance"),
        })
        .collect()
}

fn glyph_for(model: &[ModelGlyph], c: char) -> &ModelGlyph {
    model
        .iter()
        .find(|glyph| glyph.unicodes.contains(&u32::from(c)))
        .unwrap_or_else(|| panic!("no glyph encodes {c:?}"))
}

/// Reads the TTF independently of the engine: every code point of the model
/// maps to the glyph (by `post` name) with the model's rounded advance width.
fn check_ttf(ttf: &[u8], model: &[ModelGlyph]) {
    let font = FontRef::new(ttf).expect("a readable TrueType font");
    let names: Vec<String> = font
        .post()
        .expect("post")
        .glyph_names()
        .map(|(_, name)| name.to_owned())
        .collect();
    assert_eq!(names.first().map(String::as_str), Some(".notdef"));
    let cmap = font.cmap().expect("cmap");
    let hmtx = font.hmtx().expect("hmtx");
    for glyph in model {
        for &code in &glyph.unicodes {
            let c = char::from_u32(code).expect("scalar");
            let gid = cmap
                .map_codepoint(c)
                .unwrap_or_else(|| panic!("the cmap does not map {c:?}"));
            assert_ne!(gid, GlyphId::NOTDEF, "{c:?} maps to .notdef");
            let name = usize::try_from(gid.to_u32())
                .ok()
                .and_then(|index| names.get(index))
                .unwrap_or_else(|| panic!("{c:?} has no glyph name"));
            assert_eq!(name, &glyph.name, "{c:?}");
            assert_eq!(
                hmtx.advance(gid).map(f64::from),
                Some(glyph.advance_width.round()),
                "advance of {name}"
            );
        }
    }
}

/// The group key of kerning side `side` as `kerning_get` lists pairs: `@name`.
fn group_key(name: &str) -> String {
    if name.starts_with('@') {
        name.to_owned()
    } else {
        format!("@{name}")
    }
}

/// The effective kerning of `left` then `right`: glyph-glyph exception, then
/// glyph-group, group-glyph and group-group.
fn effective_kern(
    pairs: &BTreeMap<(String, String), f64>,
    first_group: &BTreeMap<String, String>,
    second_group: &BTreeMap<String, String>,
    left: &str,
    right: &str,
) -> f64 {
    let lg = first_group.get(left);
    let rg = second_group.get(right);
    let candidates = [
        Some((left.to_owned(), right.to_owned())),
        rg.map(|g| (left.to_owned(), g.clone())),
        lg.map(|g| (g.clone(), right.to_owned())),
        lg.zip(rg).map(|(a, b)| (a.clone(), b.clone())),
    ];
    candidates
        .into_iter()
        .flatten()
        .find_map(|key| pairs.get(&key).copied())
        .unwrap_or(0.0)
}

fn write_acceptance(out: &Path, root: &Path, model: &[ModelGlyph], kerning: &Value) {
    std::fs::create_dir_all(out)
        .unwrap_or_else(|error| panic!("cannot create {}: {error}", out.display()));
    for file in [
        "hito2-specimen.ttf",
        "hito2-specimen.woff2",
        "hito2-specimen.forma",
    ] {
        std::fs::copy(root.join(file), out.join(file))
            .unwrap_or_else(|error| panic!("cannot copy {file}: {error}"));
    }
    let mut first_group = BTreeMap::new();
    let mut second_group = BTreeMap::new();
    for group in kerning["groups"].as_array().expect("groups") {
        let key = group_key(group["name"].as_str().expect("group name"));
        let target = match group["side"].as_str() {
            Some("first") => &mut first_group,
            Some("second") => &mut second_group,
            other => panic!("unknown side {other:?}"),
        };
        for member in group["members"].as_array().expect("members") {
            target.insert(member.as_str().expect("member").to_owned(), key.clone());
        }
    }
    let pairs: BTreeMap<(String, String), f64> = kerning["pairs"]
        .as_array()
        .expect("pairs")
        .iter()
        .map(|pair| {
            (
                (
                    pair["first"].as_str().expect("first").to_owned(),
                    pair["second"].as_str().expect("second").to_owned(),
                ),
                pair["value"].as_f64().expect("value"),
            )
        })
        .collect();
    let letters: Vec<String> = LETTERS.iter().map(char::to_string).collect();
    let mut expected_pairs = Vec::new();
    for left in &letters {
        for right in &letters {
            let value = effective_kern(&pairs, &first_group, &second_group, left, right);
            if value != 0.0 {
                expected_pairs
                    .push(json!({ "left": left, "right": right, "value": rounded(value) }));
            }
        }
    }
    assert!(!expected_pairs.is_empty(), "no kerning among the letters");
    let glyphs: BTreeMap<&str, Value> = model
        .iter()
        .map(|glyph| {
            (
                glyph.name.as_str(),
                json!({
                    "unicodes": glyph.unicodes.iter().map(|c| unicode_text(*c)).collect::<Vec<_>>(),
                    "advance": rounded(glyph.advance_width),
                }),
            )
        })
        .collect();
    let cmap: BTreeMap<String, &str> = model
        .iter()
        .flat_map(|glyph| {
            glyph
                .unicodes
                .iter()
                .map(|c| (unicode_text(*c), glyph.name.as_str()))
        })
        .collect();
    let shaped: Vec<&str> = SHAPING_TEXT
        .chars()
        .map(|c| glyph_for(model, c).name.as_str())
        .collect();
    let expected = json!({
        "format": "family, upm; glyphs {name: {unicodes, advance}}; cmap {U+XXXX: name}; \
                   shaping {text, glyphs}; kerning [{left, right, value}] effective glyph-glyph \
                   values (nonzero, rounded to integers as HarfBuzz reports them) between the traced letters",
        "family": "Specimen Demo",
        "upm": 1000,
        "glyphs": glyphs,
        "cmap": cmap,
        "shaping": { "text": SHAPING_TEXT, "glyphs": shaped },
        "kerning": expected_pairs,
    });
    let mut text = serde_json::to_string_pretty(&expected).expect("JSON");
    text.push('\n');
    std::fs::write(out.join("hito2-expected.json"), text).expect("write expected");
}

/// An advance width rounded with [`f64::round`], as a JSON integer.
fn rounded(advance: f64) -> i64 {
    let rounded = advance.round();
    assert!(rounded.abs() < 1e9, "advance width {advance} out of range");
    // Exact: a whole number well inside the range of i64.
    rounded as i64
}
